// === Tab: mySketch ===
let particles1 = []; //1. pole castic
let num = 10000; //pocet castic

function setup() {
	createCanvas(16/9*windowHeight, windowHeight);
	background(0);

	for(let i=0;i<num;i++){
    particles1.push(createVector(random(width), random(height))) 
			//randomne rozmistime castice po obrazovce
	}
}

function draw() {
	colorMode(HSB);
	// blendMode(ADD);
	stroke (255-frameCount,95,95, 100);
  for(let i=0;i<num;i++){
    let p = particles1[i];
		point(p.x, p.y);

    p.x+=(noise(p.x/200,p.y/200,300000000)-0.54)*2;
    p.y+=(noise(p.x/200,p.y/200,30000)-0.5)*20;
  }
}

